import {gameStore,storyEngine} from '../../store/game'
import {skinStore} from '../../store/skin'
import SkinSwitch from '../../components/common/SkinSwitch.vue'
const s=gameStore.state,dark=computed(()=>skinStore.active.value==='dark')
const links=[{page:'character',label:'人物档案',en:'CHARACTERS',light:'lightCharacters',dark:'darkCharacters'},{page:'destiny',label:'重建手记',en:'WORLD ROUTES',light:'lightRoutes',dark:'darkRoutes'},{page:'evidence',label:'探索档案',en:'DISCOVERIES',light:'lightArchive',dark:'darkArchive'},{page:'gallery',label:'记忆画廊',en:'MEMORIES',light:'lightGallery',dark:'darkGallery'}] as const
function go(name:string){uni.navigateTo({url:'/pages/'+name+'/index'})}
function continueGame(){storyEngine.continueGame();uni.reLaunch({url:'/pages/play/index'})}
function begin(){storyEngine.startNewGame();uni.reLaunch({url:'/pages/play/index'})}
function startNew(){if(!s.hasSave){begin();return}uni.showModal({title:'开启新的旅程',content:'当前周目将保留在归档中，已解锁的皮肤继续保留。',success:r=>{if(r.confirm)begin()}})}
